import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

rms_norm_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void rms_norm_kernel(const float* input, float* output, 
                              int num_features, int inner_size,
                              float eps, int total_elements) {
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total_elements) return;

    const int inner_idx = idx % inner_size;
    const int batch_idx = idx / inner_size;

    __shared__ float shared_sum[1];
    float sum = 0.0f;

    for (int f = 0; f < num_features; ++f) {
        const int input_idx = batch_idx * num_features * inner_size + 
                             f * inner_size + inner_idx;
        const float val = input[input_idx];
        sum += val * val;
    }

    sum = blockReduceSum(sum);

    if (threadIdx.x == 0) {
        shared_sum[0] = rsqrtf(sum / num_features + eps);
    }
    __syncthreads();

    const float scale = shared_sum[0];
    const int output_idx = batch_idx * num_features * inner_size + 
                          threadIdx.x * inner_size + inner_idx;

    if (threadIdx.x < num_features) {
        output[output_idx] = input[output_idx] * scale;
    }
}

torch::Tensor rms_norm_cuda(torch::Tensor input, int num_features, float eps) {
    const int batch_size = input.size(0);
    const int inner_size = input.numel() / (batch_size * num_features);

    auto output = torch::empty_like(input);
    const int total_elements = batch_size * inner_size;

    const int threads_per_block = 256;
    const int blocks = (total_elements + threads_per_block - 1) / threads_per_block;

    rms_norm_kernel<<<blocks, threads_per_block>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        num_features,
        inner_size,
        eps,
        total_elements
    );

    return output;
}

// Helper function for block-wide sum reduction
__device__ float blockReduceSum(float val) {
    __shared__ float shared[32];
    int lane = threadIdx.x % warpSize;
    int wid = threadIdx.x / warpSize;

    val = warpReduceSum(val);

    if (lane == 0) shared[wid] = val;
    __syncthreads();

    val = (threadIdx.x < blockDim.x / warpSize) ? shared[lane] : 0.0f;
    val = warpReduceSum(val);
    return val;
}

__device__ float warpReduceSum(float val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}
"""

rms_norm_cpp_source = "torch::Tensor rms_norm_cuda(torch::Tensor input, int num_features, float eps);"

rms_norm = load_inline(
    name='rms_norm',
    cpp_sources=rms_norm_cpp_source,
    cuda_sources=rms_norm_cuda_source,
    functions=['rms_norm_cuda'],
    verbose=True,
    extra_cuda_cflags=['-O2']
)

class ModelNew(nn.Module):
    def __init__(self, num_features: int, eps: float = 1e-5):
        super().__init__()
        self.num_features = num_features
        self.eps = eps

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return rms_norm.rms_norm_cuda(x, self.num_features, self.eps)
